def negative_revenue(item: tuple[str, int]) -> int:
    """Построить ключ убывания выручки."""
    return -item[1]


def sales_example() -> None:
    """Выполнить все пять запросов примера о продажах."""
    sales = (
        ("Алия", "ноутбук", "техника", 2, 380_000),
        ("Борис", "чайник", "быт", 5, 12_000),
        ("Алия", "мышь", "техника", 10, 6_000),
        ("Галым", "ноутбук", "техника", 1, 395_000),
        ("Борис", "пылесос", "быт", 2, 85_000),
    )
    managers = sorted({manager for manager, *_ in sales})
    revenue = {
        manager: sum(
            quantity * price for name, _, _, quantity, price in sales if name == manager
        )
        for manager in managers
    }
    best = max(revenue, key=revenue.__getitem__)
    categories = {category for _, _, category, _, _ in sales}
    all_positive = all(quantity > 0 and price > 0 for *_, quantity, price in sales)
    by_item = sorted(
        ((item, quantity * price) for _, item, _, quantity, price in sales),
        key=negative_revenue,
    )
    print("Выручка по менеджерам:", revenue)
    print("Лучший менеджер:", best)
    print("Категории:", sorted(categories), "| Все суммы положительны:", all_positive)
    print(
        "\n".join(
            f"{place}. {item:<8} {total:>9,}".replace(",", " ")
            for place, (item, total) in enumerate(by_item, start=1)
        )
    )
    assert revenue == {"Алия": 820000, "Борис": 230000, "Галым": 395000}
    assert best == "Алия" and categories == {"быт", "техника"} and all_positive
    assert by_item[-2:] == [("чайник", 60000), ("мышь", 60000)]

def remove_all(lst: list[T], x: T) -> list[T]:
    """Вернуть новый список без всех значений, равных x."""
    return [item for item in lst if item != x]

def rename_key(d: dict[K, V], old: K, new: K) -> dict[K, V]:
    """Переименовать ключ; отсутствие и коллизия вызывают ошибку."""
    if old not in d:
        raise KeyError(old)
    if new is not old and new != old and new in d:
        raise ValueError("Новый ключ уже существует")
    return {new if key is old or key == old else key: value for key, value in d.items()}

def update_in(
    d: dict[K, Any],
    path: tuple[K, ...],
    value: Any,
) -> dict[K, Any]:
    """Создать копии словарей вдоль непустого пути и установить value."""
    if not isinstance(path, tuple) or not path:
        raise ValueError("Путь должен быть непустым кортежем")
    key, *tail = path
    if not tail:
        return {**d, key: value}
    child = d.get(key, {})
    if not isinstance(child, dict):
        raise TypeError("Промежуточное значение не является словарём")
    return {**d, key: update_in(child, tuple(tail), value)}

def toggle(s: set[T], x: T) -> set[T]:
    """Вернуть множество с переключённым присутствием x."""
    return s ^ {x}

def odd_squares() -> list[int]:
    """Получить квадраты нечётных чисел от 1 до 30 включительно."""
    return [number**2 for number in range(1, 31) if number % 2 != 0]

def multiplication_table() -> list[list[int]]:
    """Построить таблицу умножения для индексов от 1 до 5."""
    return [[i * j for j in range(1, 6)] for i in range(1, 6)]


def transpose(matrix: list[list[int]]) -> list[list[int]]:
    """Транспонировать прямоугольную матрицу; пустая даёт []."""
    return [[row[j] for row in matrix] for j in range(len(matrix[0]))] if matrix else []

def flatten(rows: list[list[int]]) -> list[int]:
    """Развернуть один уровень вложенности списка."""
    return [value for row in rows for value in row]

def word_lengths(sentence: str) -> dict[str, int]:
    """Убрать крайние знаки препинания и измерить слова от 3 букв."""
    return {
        word: len(word)
        for token in sentence.split()
        if len(word := token.strip(".,!?;:")) >= 3
    }

def invert_groups(data: dict[str, int]) -> dict[int, list[str]]:
    """Сгруппировать все исходные ключи по их значениям."""
    return {
        value: [key for key, item in data.items() if item == value]
        for value in data.values()
    }

def vowels(text: str) -> set[str]:
    """Получить русские и латинские гласные без учёта регистра."""
    return {char for char in text.lower() if char in "аеёиоуыэюяaeiou"}

def pythagorean_triples() -> list[tuple[int, int, int]]:
    """Найти все, включая непримитивные, тройки a < b < c <= 50."""
    return [
        (a, b, c)
        for a in range(1, 51)
        for b in range(a + 1, 51)
        for c in range(b + 1, 51)
        if a * a + b * b == c * c
    ]

def primes() -> list[int]:
    """Найти простые числа до 100 проверкой делителей до корня."""
    return [
        number
        for number in range(2, 101)
        if all(number % divisor for divisor in range(2, isqrt(number) + 1))
    ]

def uppercase_positions(text: str) -> list[tuple[int, str]]:
    """Вернуть индексы с нуля и символы всех заглавных букв."""
    return [(index, char) for index, char in enumerate(text) if char.isupper()]

def digit_sum() -> int:
    """Сложить цифры всех чисел от 1 до 1000 включительно."""
    return sum(int(digit) for number in range(1, 1001) for digit in str(number))

def average(student: Student) -> float:
    """Вычислить среднее; запись без оценок считать некорректной."""
    grades = student[2]
    if not grades:
        raise ValueError("У студента отсутствуют оценки")
    return sum(grades) / len(grades)


def best_student(students: list[Student]) -> Student:
    """Выбрать максимальный балл; при равенстве первую запись."""
    return max(students, key=average)

def group_order(student: Student) -> tuple[str, float]:
    """Создать ключ сортировки по группе и убыванию среднего."""
    return student[1], -average(student)


def by_group(students: list[Student]) -> list[Student]:
    """Стабильно отсортировать по группе и убыванию среднего."""
    return sorted(students, key=group_order)

def has_all_at_least_70(students: list[Student]) -> bool:
    """Проверить наличие студента с непустым набором оценок >= 70."""
    return any(
        bool(grades) and all(grade >= 70 for grade in grades)
        for _, _, grades in students
    )

def parallel_columns(
    students: list[Student],
) -> tuple[tuple[str, ...], tuple[float, ...]]:
    """Развернуть пары фамилия/средний балл в два кортежа."""
    return (
        tuple(zip(*((record[0], average(record)) for record in students), strict=True))
        if students
        else ((), ())
    )

def ranking(students: list[Student]) -> list[tuple[int, str, float]]:
    """Построить нумерованный с единицы стабильный рейтинг."""
    return [
        (place, student[0], average(student))
        for place, student in enumerate(
            sorted(students, key=average, reverse=True), start=1
        )
    ]

def group_counts(students: list[Student]) -> dict[str, int]:
    """Посчитать студентов каждой группы без изменения данных."""
    return {
        group: sum(student_group == group for _, student_group, _ in students)
        for group in sorted({group for _, group, _ in students})
    }

def valid_size(value: object) -> bool:
    """Разрешить неотрицательные размеры, представимые конечным float."""
    if not isinstance(value, (int, float)) or isinstance(value, bool):
        return False
    try:
        return isfinite(value) and value >= 0
    except OverflowError:
        return False


def finite_area(value: float) -> float | None:
    """Вернуть площадь либо None, если результат не помещается в float."""
    return value if isfinite(value) else None


def area(shape: object) -> float | None:
    """Вычислить площадь допустимого кортежа или вернуть None."""
    if not isinstance(shape, tuple):
        return None
    match shape:
        case ("circle", r) if valid_size(r):
            return finite_area(pi * r * r)
        case ("rect", w, h) if valid_size(w) and valid_size(h):
            return finite_area(float(w) * float(h))
        case ("square", a) if valid_size(a):
            return finite_area(float(a) * float(a))
        case ("triangle", a, b, c) if (
            all(valid_size(side) for side in (a, b, c))
            and a + b > c
            and a + c > b
            and b + c > a
        ):
            # Нормирование предотвращает переполнение произведения Герона.
            scale = max(a, b, c)
            x, y, z = a / scale, b / scale, c / scale
            semiperimeter = (x + y + z) / 2
            factor = sqrt(
                max(
                    0.0,
                    semiperimeter
                    * (semiperimeter - x)
                    * (semiperimeter - y)
                    * (semiperimeter - z),
                )
            )
            return finite_area(factor * scale * scale)
        case _:
            return None

def total_area(shapes: list[Shape]) -> float:
    """Суммировать допустимые площади одним выражением."""
    return sum(value for shape in shapes if (value := area(shape)) is not None)
